#!/bin/bash
# Setup for Question 7: CSR approval
# Create a certificate signing request that sits Pending until the student approves it

kubectl delete csr app-web-csr 2>/dev/null || true

cat <<'MANIFEST' | kubectl apply -f -
apiVersion: certificates.k8s.io/v1
kind: CertificateSigningRequest
metadata:
  name: app-web-csr
spec:
  request: 
  signerName: kubernetes.io/kubelet-serving
  usages:
  - server auth
MANIFEST

# If the control plane auto-processed the CSR, recreate it so it starts Pending
CONDITION=$(kubectl get csr app-web-csr -o jsonpath='{.status.conditions[0].type}' 2>/dev/null)
if [ -n "$CONDITION" ]; then
  echo "CSR was auto-processed ($CONDITION); recreating a fresh pending request"
  kubectl delete csr app-web-csr 2>/dev/null || true
  cat <<'MANIFEST' | kubectl apply -f -
apiVersion: certificates.k8s.io/v1
kind: CertificateSigningRequest
metadata:
  name: app-web-csr
spec:
  request: 
  signerName: kubernetes.io/kubelet-serving
  usages:
  - server auth
MANIFEST
fi
exit 0
